INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Schwachstellenanalyse immer ein manueller Prozess?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisierte Tools können helfen"}, {"text": "Ja", "correct": false, "because": "Kombination ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutze ich primär für eine Schwachstellenanalyse?', 3, '[{"text": "Penetrationstest", "correct": true, "because": "Simuliert echte Angriffe"}, {"text": "Code-Optimierung", "correct": false, "because": "Nicht sicherheitsrelevant"}, {"text": "Datenbank-Backup", "correct": false, "because": "Schutz, kein Test"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze gehören zur Schwachstellenanalyse?', 5, '[{"text": "Code-Reviews", "correct": true, "because": "Findet Schwächen im Quelltext"}, {"text": "Penetrationstests", "correct": true, "because": "Testet Systeme aktiv"}, {"text": "Farbanpassung", "correct": false, "because": "Kein Sicherheitsaspekt"}, {"text": "UI-Design", "correct": false, "because": "Ästhetisch, nicht sicherheitstechnisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schwachstellenanalysen finden Sicherheitslücken. b) Sie verhindern Angriffe direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verhinderung ist separates Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Schwachstellenanalyse?', 4, '[{"text": "Netzwerkkonfiguration", "correct": false, "because": "Kritischer Bereich"}, {"text": "Softwareversionen", "correct": false, "because": "Häufige Schwachstellenquelle"}, {"text": "Farbschema der UI", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Penetrationstest auch interne Schwächen findet?', 2, '[{"text": "Ja", "correct": true, "because": "Interne Tests sind möglich"}, {"text": "Nein", "correct": false, "because": "Umfang hängt vom Test ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für automatisierte Schwachstellenanalysen?', 3, '[{"text": "Nessus", "correct": true, "because": "Beliebt für Scans"}, {"text": "Photoshop", "correct": false, "because": "Für Design, nicht Sicherheit"}, {"text": "Excel", "correct": false, "because": "Kein Analysetool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zu einem Penetrationstest?', 5, '[{"text": "Reconnaissance", "correct": true, "because": "Sammelt Informationen"}, {"text": "Exploitation", "correct": true, "because": "Nutzt Schwächen aus"}, {"text": "Datenbankdesign", "correct": false, "because": "Nicht testrelevant"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Sicherheitsfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Schwachstellenanalysen sind proaktiv. b) Sie sind nur nach Angriffen nützlich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prävention ist Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Schwachstellenanalyse?', 4, '[{"text": "Zugriff auf Systeme", "correct": false, "because": "Notwendig für Tests"}, {"text": "Schwachstellendatenbank", "correct": false, "because": "Hilft bei Identifikation"}, {"text": "Grafikdesign-Software", "correct": true, "because": "Kein Sicherheitszweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Testet eine Schwachstellenanalyse auch Benutzerfehler?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf technische Lücken"}, {"text": "Ja", "correct": false, "because": "Soziale Aspekte separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche prüfe ich bei einer Schwachstellenanalyse?', 4, '[{"text": "Netzwerk", "correct": true, "because": "Häufige Angriffsfläche"}, {"text": "Anwendungen", "correct": true, "because": "Potenzielle Schwächen"}, {"text": "Farbschemata", "correct": false, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Penetrationstests illegal sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Legal mit Erlaubnis"}, {"text": "Ja", "correct": false, "because": "Nur ohne Zustimmung illegal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Schwachstellenanalyse?', 3, '[{"text": "Kritische Systeme", "correct": true, "because": "Höchstes Risiko"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Nicht sicherheitsrelevant"}, {"text": "Datenbankgröße", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Code-Reviews finden Schwachstellen. b) Sie ersetzen Penetrationstests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests sind ergänzend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools helfen bei der Schwachstellenanalyse?', 5, '[{"text": "Wireshark", "correct": true, "because": "Analysiert Netzwerkverkehr"}, {"text": "Metasploit", "correct": true, "because": "Für Penetrationstests"}, {"text": "Figma", "correct": false, "because": "Für Design, nicht Sicherheit"}, {"text": "Notepad", "correct": false, "because": "Kein Analysetool"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Penetrationstest unwichtig?', 3, '[{"text": "Angriffssimulation", "correct": false, "because": "Kern des Tests"}, {"text": "Schwachstellenidentifikation", "correct": false, "because": "Hauptziel"}, {"text": "Typografie", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit der Analyse? Ist sie nur für Software?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Hardware und Netzwerke"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Schwachstellenanalysen regelmäßig nötig sind?', 2, '[{"text": "Ja", "correct": true, "because": "Neue Schwächen entstehen"}, {"text": "Nein", "correct": false, "because": "Einmalig reicht nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Penetrationstest?', 4, '[{"text": "Sicherheitslücken aufdecken", "correct": true, "because": "Simuliert Angriffe"}, {"text": "UI verbessern", "correct": false, "because": "Kein Designfokus"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Schutzmaßnahme"}]');
